<?php
namespace App\Http\Requests;use Illuminate\Foundation\Http\FormRequest;class ProductRequest extends FormRequest{public function authorize():bool{return $this->user()?->role==='admin';}public function rules():array{return['category_id'=>'required|exists:categories,id','name'=>'required|string|max:160','description'=>'required|string|max:5000','price'=>'required|numeric|min:0|max:99999999.99','stock'=>'required|integer|min:0','image_url'=>'nullable|url|max:255','is_active'=>'boolean'];}}
